package app.kinnect.live;
import android.graphics.*;import android.graphics.drawable.Drawable;
/** Semantic ColorOS-inspired soft tile. Control glyphs remain monochrome for legibility. */
final class FlowIconDrawable extends Drawable {
 private final Drawable glyph;private final Paint paint=new Paint(3);private final int top,bottom;private int alpha=255;
 FlowIconDrawable(Drawable drawable,String name){glyph=drawable.mutate();int[] colors=palette(name);top=colors[0];bottom=colors[1];glyph.setTint(Color.WHITE);}
 static int[] palette(String name){String n=name.toLowerCase();if(n.contains("trash")||n.contains("block")||n.contains("log_out")||n.contains("off")&&n.contains("location"))return new int[]{0xffd94e61,0xffb7354d};if(n.contains("heart")||n.contains("live")||n.contains("radio"))return new int[]{0xffd44d88,0xffae3273};if(n.contains("message")||n.contains("inbox")||n.contains("phone")||n.contains("call"))return new int[]{0xff299f7e,0xff137c64};if(n.contains("wallet")||n.contains("shopping")||n.contains("gift"))return new int[]{0xffc97628,0xffa8551b};if(n.contains("video")||n.contains("clapper")||n.contains("image"))return new int[]{0xffd9684b,0xffb8483a};if(n.contains("compass")||n.contains("shield")||n.contains("lock")||n.contains("location")||n.contains("distance"))return new int[]{0xff3885cb,0xff2863aa};return new int[]{0xff8966db,0xff6946bf};}
 public void draw(Canvas canvas){Rect b=getBounds();float radius=b.width()*.3f;paint.setAlpha(alpha);paint.setStyle(Paint.Style.FILL);paint.setShader(new LinearGradient(b.left,b.top,b.right,b.bottom,top,bottom,Shader.TileMode.CLAMP));canvas.drawRoundRect(new RectF(b),radius,radius,paint);paint.setShader(null);paint.setColor(Color.WHITE);paint.setAlpha(Math.round(alpha*.22f));paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(Math.max(1,b.width()/40f));RectF rim=new RectF(b);rim.inset(1,1);canvas.drawRoundRect(rim,radius-1,radius-1,paint);paint.setStyle(Paint.Style.FILL);int inset=Math.round(b.width()*.22f);glyph.setBounds(b.left+inset,b.top+inset,b.right-inset,b.bottom-inset);glyph.draw(canvas);}
 public void setAlpha(int a){alpha=a;glyph.setAlpha(a);invalidateSelf();}public void setColorFilter(ColorFilter f){glyph.setColorFilter(f);invalidateSelf();}public int getOpacity(){return PixelFormat.TRANSLUCENT;}public int getIntrinsicWidth(){return 38;}public int getIntrinsicHeight(){return 38;}
}
